(()=>{const choices={ac:['AC is running but not cooling','Water is leaking from the AC','AC does not turn on','Service and cleaning needed'],plumbing:['Tap or pipe is leaking','Drain is blocked','Low water pressure','Toilet flush is not working'],electrical:['Switch or socket is not working','Power trips frequently','Fan or light is not working','New wiring or fixture needed'],washing:['Machine is not draining','Machine is not spinning','Water is leaking from the machine','Machine does not start']};const baseRender=render;render=function(){baseRender();if(!localToken||!localUser||role!=='customer'||view!=='form'||step!==1)return;const form=document.querySelector('#booking-form'),issue=form?.elements.issue;if(!issue||form.dataset.issueSuggestions)return;form.dataset.issueSuggestions='ready';const items=choices[service]||[];issue.placeholder=items[0]||'Describe the problem';const panel=document.createElement('section');panel.className='issue-suggestions';panel.innerHTML=`<small>QUICK DESCRIPTION</small><div>${items.map((item,index)=>`<button type="button" data-issue="${index}">${esc(item)}</button>`).join('')}</div>`;issue.closest('label').after(panel);panel.querySelectorAll('[data-issue]').forEach(button=>button.onclick=()=>{issue.value=items[Number(button.dataset.issue)];issue.dispatchEvent(new Event('input',{bubbles:true}));issue.focus();});};})();
